Implement token creation via reflection functions:

private Token.StartTag startTag(String name, boolean selfClosing) {
   Token.StartTag t = new Token.StartTag();
   // set fields via reflection
   try {
      java.lang.reflect.Field typeField = Token.class.getDeclaredField("type");
      typeField.setAccessible(true);
      typeField.set(t, Token.Type.StartTag);
      java.lang.reflect.Field nameField = Token.StartTag.class.getDeclaredField("name");
      nameField.setAccessible(true);
      nameField.set(t, name);
      java.lang.reflect.Field selfClosingField = Token.StartTag.class.getDeclaredField("selfClosing");
      selfClosingField.setAccessible(true);
      selfClosingField.setBoolean(t, selfClosing);
      // attributes
      java.lang.reflect.Field attrField = Token.StartTag.class.getDeclaredField("attributes");
      attrField.setAccessible(true);
      attrField.set(t, new Attributes());
   } catch (Exception e) { throw new RuntimeException(e); }
   return t;
}

